import { NextRequest, NextResponse } from "next/server";
import { proxyToTjApi } from "@/lib/tjApiProxy";

export const dynamic = "force-dynamic";

const MEGAMENU_TTL_MS = 60_000;
const MEGAMENU_CACHE_MAX_KEYS = 250;

const megamenuCache = new Map<
  string,
  {
    data: unknown;
    ts: number;
  }
>();

function evictOldestEntries(): void {
  while (megamenuCache.size > MEGAMENU_CACHE_MAX_KEYS) {
    const oldestKey = megamenuCache.keys().next().value as string | undefined;
    if (!oldestKey) break;
    megamenuCache.delete(oldestKey);
  }
}

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ slug: string }> },
) {
  const { slug } = await params;
  if (!/^[a-z0-9](?:[a-z0-9-]{0,198}[a-z0-9])?$/.test(slug)) {
    return NextResponse.json({ error: "Slug non valido" }, { status: 400 });
  }

  const pathname = request.nextUrl.pathname;
  const now = Date.now();
  const cached = megamenuCache.get(slug);

  if (cached && now - cached.ts < MEGAMENU_TTL_MS) {
    console.log("[WP Proxy]", "GET", pathname, 200);
    return NextResponse.json(cached.data, {
      status: 200,
      headers: {
        "Content-Type": "application/json",
        "Cache-Control": "public, max-age=60",
      },
    });
  }

  const res = await proxyToTjApi(request);
  const text = await res.text();

  if (res.ok) {
    try {
      const data = JSON.parse(text) as unknown;
      megamenuCache.set(slug, { data, ts: Date.now() });
      evictOldestEntries();
    } catch {
      /* non JSON: non cache, pass-through sotto */
    }
    return new NextResponse(text, {
      status: res.status,
      headers: new Headers(res.headers),
    });
  }

  if (cached) {
    // Upstream in errore ma cache (anche scaduta) disponibile: stale-if-error.
    console.log("[WP Proxy]", "GET", pathname, 200);
    return NextResponse.json(cached.data, {
      status: 200,
      headers: {
        "Cache-Control": "no-store",
        Warning: '110 - "Response is stale"',
      },
    });
  }

  // Errore upstream senza cache: non mascherare come 200 + [] (outage invisibile).
  // Il consumer (lib/tjApiClient.ts fetchMegamenu) gestisce la risposta non-ok
  // restituendo lista vuota senza crash.
  console.log("[WP Proxy]", "GET", pathname, 503);
  return NextResponse.json(
    { error: "Megamenu non disponibile" },
    {
      status: 503,
      headers: { "Cache-Control": "no-store" },
    },
  );
}
